import type { FastifyPluginAsyncZod } from "fastify-type-provider-zod";
import { z } from "zod";
import { and, eq, gte, isNull, lte } from "drizzle-orm";
import { expenses } from "../../../db/schema.js";

const Query = z.object({
  from: z.coerce.date().optional(),
  to: z.coerce.date().optional(),
  cat: z.string().optional(),
});

export const listExpenses: FastifyPluginAsyncZod = async (app) => {
  app.get("/expenses", { schema: { querystring: Query } }, async (req) => {
    const { from, to, cat } = req.query;
    const rows = await app.db
      .select()
      .from(expenses)
      .where(
        and(
          eq(expenses.orgId, req.auth.orgId),
          isNull(expenses.deletedAt),
          from ? gte(expenses.incurredAt, from) : undefined,
          to ? lte(expenses.incurredAt, to) : undefined,
          cat ? eq(expenses.category, cat) : undefined,
        ),
      )
      .orderBy(expenses.incurredAt);
    return { data: rows };
  });
};

